def probe():
    """探测 FES 数据接收上限: 用安全的 DRAM 类型 (0x17f00) 测试不同大小"""
    print('[探测] 等待设备 (FES 模式) ...')
    dev = None
    for attempt in range(10):
        dev = find_device(10)
        if dev is None:
            continue
        try:
            dev, ep_out, ep_in = open_device(dev)
            break
        except Exception as e:
            print('   [WARN] 打开失败 (%s)' % e)
            dev = None
            time.sleep(2)
    if dev is None:
        print('[探测] 未找到设备')
        return False

    # 握手
    vd, status = fes_cmd_full(dev, ep_out, ep_in, 1,
                              struct.pack('<HH12s', APP_VERIFY_DEV, 1, b'\0' * 12), 32)
    print('[探测] verify: %s status=%d' % (vd[:8], status))
    if vd[:8] != b'AWUSBFEX':
        return False

    for size in (0x1000, 0x4000, 0x8000, 0xA000, 0xB000):
        tag = size // 0x1000 + 10
        # fes_down: DRAM|FINISH (0x17f00), 无 BOOT0 标记 -> 完成时不做任何事, 安全
        trans = struct.pack('<HHIII', FEX_CMD_fes_down, 1, 0x80000000, size, 0x17f00)
        try:
            magic, ctag, residue, status = fes_send_cmd(dev, ep_out, ep_in, tag, trans)
            dev.write(ep_out, fes_cbw(tag + 1, TL_CMD_RECEIVE, size), timeout=30000)
            data = b'\xAA' * size
            for off in range(0, size, 16384):
                dev.write(ep_out, data[off:off + 16384], timeout=60000)
            magic, ctag, residue, status = fes_read_csw(dev, ep_in, 60000)
            ok = (magic == CSW_MAGIC and status == 0)
            print('[探测] 0x%x (%d B): %s (CSW magic=0x%08x status=%d)'
                  % (size, size, '✅ 成功' if ok else '❌ 失败', magic, status))
            if not ok:
                print('[探测] 上限在 0x%x 以下' % size)
                return False
        except Exception as e:
            print('[探测] 0x%x (%d B): ❌ 异常 %s' % (size, size, e))
            return False
    print('[探测] 0xB000 (45KB) 接收成功 -> boot0 烧写可行')
    return True


